/**
 * contracts/assets.manifest.json (REQ-ASSET-008): every asset key the master data can make the client
 * ask for, grouped by kind with the kind's fallback key. Generated by `npm run gen:assets`; a test fails
 * when master data and the committed manifest drift apart.
 */
import { silksEditorOf } from './silksEditor.js';
import type { Master } from './master.js';
import { DIRT_GOINGS, TURF_GOINGS } from './schemas.js';
import { stableConfig } from './stable.js';
import { showcaseOf } from './showcase.js';
import { collectionOf } from './collection.js';
import { stampAsset, stampsOf } from './teamFeed.js';
import { commentaryPacksOf } from './commentaryPacks.js';
import { PHOTO_CATEGORIES, photoAsset, photoOf } from './photoMode.js';
import { ASSET_KEY_RE, ASSET_KINDS, assetKeys, collectItemIds, fallbackKey, kindOf, VISUALS, type VisualsMaster } from './visuals.js';

/** engine/Muchi.Client/Resources/Muchi/commentary-ja.json (only the parts the manifest needs). */
export interface CommentaryJson { phrases: Record<string, { variants: { id: string; text: string }[] }> }

/** Fixed clip ids of a template text, split exactly like Muchi.Client Commentary (`<variantId>#<n>`). */
export function phraseClipIds(variantId: string, text: string): string[] {
  const out: string[] = [];
  let i = 0;
  let n = 0;
  while (i < text.length) {
    const open = text.indexOf('{', i);
    if (open < 0) { out.push(`${variantId}#${n++}`); break; }
    if (open > i) out.push(`${variantId}#${n++}`);
    const close = text.indexOf('}', open);
    if (close < 0) throw new Error(`unclosed placeholder in ${variantId}`);
    i = close + 1;
  }
  return out;
}

/** Highest place number the commentary can speak (field size). */
export const MAX_SPOKEN_NUMBER = 12;

export interface AssetManifest {
  _note: string;
  version: number;
  kinds: Record<string, { fallback: string; description: string; dynamic: boolean; count: number }>;
  keys: string[];
}

export function buildAssetManifest(m: Master, commentary: CommentaryJson, v: VisualsMaster = VISUALS): AssetManifest {
  const keys = new Set<string>();
  const add = (k: string) => keys.add(k);
  const hz = v.horse;
  hz.coats.forEach((x) => add(assetKeys.coat(x.id)));
  hz.faces.forEach((x) => add(assetKeys.face(x.id)));
  hz.legs.forEach((x) => add(assetKeys.leg(x.id)));
  hz.manes.forEach((x) => add(assetKeys.mane(x.id)));
  hz.builds.forEach((x) => add(assetKeys.build(x.id)));
  v.silks.patterns.forEach((p) => add(assetKeys.silksPattern(p.id)));
  v.silks.caps.forEach((c) => add(assetKeys.silksCap(c.id)));
  // REQ-SILK-*: 勝負服エディタ sleeve and cap masks (special colours get a swatch icon through their silks_part cosmetic)
  silksEditorOf(m).sleeves.forEach((x) => add(assetKeys.silksSleeve(x.id)));
  silksEditorOf(m).caps.forEach((x) => add(assetKeys.silksCap(x.id)));
  v.gateBrackets.forEach((g) => add(assetKeys.gate(g.bracket)));
  collectItemIds(m, v).forEach((id) => add(assetKeys.item(id)));
  for (const c of m.items?.cosmetics ?? []) if (c.kind !== 'silks') add(c.asset); // tack/*, decor/* (REQ-ITEM-006), stamp/*
  stampsOf(m).stamps.forEach((s) => add(stampAsset(s.id))); // REQ-TEAMFEED-001: every team-feed stamp
  for (const cat of PHOTO_CATEGORIES) photoOf(m)[cat].forEach((d) => add(photoAsset(cat, d.id))); // REQ-PHOTO-005: every photo look / frame / stamp
  stableConfig(m).themes.forEach((t) => add(assetKeys.stableTheme(t.id))); // REQ-STABLE-001
  showcaseOf(m).backgrounds.forEach((b) => add(assetKeys.showcaseBg(b.id))); // REQ-SHOW-006
  m.gacha.banners.forEach((b) => add(assetKeys.gachaBanner(b.id)));
  m.events.forEach((e) => add(assetKeys.eventBanner(e.id)));
  m.titles.forEach((t) => add(assetKeys.title(t.id)));
  // REQ-COL-003 / REQ-ACH-004: 図鑑 art per template (portrait + unknown silhouette) and a badge per achievement tier
  m.templates.forEach((t) => { add(assetKeys.collectionPortrait(t.id)); add(assetKeys.collectionSilhouette(t.id)); });
  collectionOf(m).achievements.forEach((d) => d.tiers.forEach((t) => add(assetKeys.badge(d.id, t.tier))));
  v.emblem.shapes.forEach((x) => add(assetKeys.emblemShape(x)));
  v.emblem.symbols.forEach((x) => add(assetKeys.emblemSymbol(x)));
  for (const t of m.tracks) {
    const venue = v.tracks[t.id]?.venue;
    if (!venue) continue;
    add(assetKeys.venue(venue));
    add(assetKeys.surface(venue, t.surface));
    if (m.litTracks.has(t.id)) add(assetKeys.night(venue));
  }
  for (const g of new Set<string>([...TURF_GOINGS, ...DIRT_GOINGS])) if (g !== 'good') add(assetKeys.going(g));
  (v.courseLooks ?? []).forEach((l) => add(l.key));
  (v.weather ?? []).forEach((w) => add(assetKeys.weather(w)));
  v.sfx.race.forEach((x) => add(assetKeys.sfxRace(x)));
  v.sfx.ui.forEach((x) => add(assetKeys.sfxUi(x)));
  for (const p of Object.values(commentary.phrases)) for (const vr of p.variants) phraseClipIds(vr.id, vr.text).forEach((c) => add(assetKeys.voicePhrase(c)));
  // REQ-CMT-006: every commentary pack's fixed fragments (same splitting; names and numbers are shared)
  for (const p of commentaryPacksOf(m).packs) for (const ph of Object.values(p.phrases?.ja ?? {})) for (const vr of ph.variants) phraseClipIds(vr.id, vr.text).forEach((c) => add(assetKeys.voicePhrase(c)));
  for (let n = 1; n <= MAX_SPOKEN_NUMBER; n++) add(assetKeys.voiceNum(n));
  m.templates.forEach((t) => add(assetKeys.voiceName(t.name)));
  m.skills?.skills.forEach((s) => add(assetKeys.voiceName(s.name))); // REQ-UXS-050: skill names are voiced like horse names
  for (const kind of Object.keys(ASSET_KINDS)) add(fallbackKey(kind));

  const sorted = [...keys].sort();
  const kinds: AssetManifest['kinds'] = {};
  for (const [kind, d] of Object.entries(ASSET_KINDS)) {
    kinds[kind] = { fallback: fallbackKey(kind), description: d.description, dynamic: d.dynamic === true, count: sorted.filter((k) => kindOf(k) === kind).length };
  }
  return {
    _note: '生成ファイル（npm run gen:assets）。手で編集しない。キーの規則と各kindの意味は contracts/assets.md。dynamic なkindは実行時に増える（ここには既知のものだけ載る）。',
    version: v.version, kinds, keys: sorted,
  };
}

/** Problems in a manifest: malformed keys, keys of unknown kinds, missing fallbacks. */
export function manifestProblems(man: AssetManifest): string[] {
  const p: string[] = [];
  const set = new Set(man.keys);
  for (const k of man.keys) {
    if (!ASSET_KEY_RE.test(k)) p.push(`malformed key ${k}`);
    else if (!man.kinds[kindOf(k)]) p.push(`key ${k} has unknown kind ${kindOf(k)}`);
  }
  for (const [kind, d] of Object.entries(man.kinds)) if (!set.has(d.fallback)) p.push(`kind ${kind}: fallback ${d.fallback} missing`);
  if (new Set(man.keys).size !== man.keys.length) p.push('duplicate keys');
  return p;
}
